grid.script:
function widget(project, params, ctx) {
  const walls = project.walls.filter(w => w.level === ctx.level && (w.kind === 'bearing' || w.kind === 'partition'));
  if (!walls.length) return [];
  let x0 = Infinity, y0 = Infinity, x1 = -Infinity, y1 = -Infinity;
  for (const w of walls) for (const [x, y] of [w.start, w.end]) {
    x0 = Math.min(x0, x); y0 = Math.min(y0, y); x1 = Math.max(x1, x); y1 = Math.max(y1, y);
  }
  const s = params.spacing;
  const ox = params.originX ?? x0, oy = params.originY ?? y0;
  const margin = 1500;
  // Grid lines from the origin over the walls' extent, in both directions
  const xs = [], ys = [];
  for (let x = ox - Math.floor((ox - x0) / s) * s; x <= x1 + 1; x += s) xs.push(x);
  for (let y = oy - Math.floor((oy - y0) / s) * s; y <= y1 + 1; y += s) ys.push(y);
  const items = [];
  xs.forEach((x, i) => {
    items.push({ type: 'line', from: [x, y0 - margin], to: [x, y1 + margin], dash: [6, 3] });
    items.push({ type: 'label', at: [x, y0 - margin - 600], text: String(i + 1) });
  });
  ys.forEach((y, i) => {
    items.push({ type: 'line', from: [x0 - margin, y], to: [x1 + margin, y], dash: [6, 3] });
    items.push({ type: 'label', at: [x0 - margin - 600, y], text: i < 26 ? String.fromCharCode(65 + i) : 'A' + (i - 25) });
  });
  items.push({ type: 'handle', at: [ox, oy], x: 'originX', y: 'originY' });
  if (params.snap) for (const x of xs) for (const y of ys) items.push({ type: 'snap', at: [x, y] });
  return items;
}

axes.script:
function widget(project, params, ctx) {
  const walls = project.walls.filter(w => w.level === ctx.level);
  let x0 = 0, y0 = 0;
  if (walls.length) {
    x0 = Math.min(...walls.flatMap(w => [w.start[0], w.end[0]]));
    y0 = Math.min(...walls.flatMap(w => [w.start[1], w.end[1]]));
  }
  const ox = params.originX ?? x0, oy = params.originY ?? y0;
  const L = params.length, t = params.tick, h = 120;
  const items = [
    { type: 'line', from: [ox, oy], to: [ox + L, oy] },
    { type: 'line', from: [ox + L, oy], to: [ox + L - 250, oy - 120] },
    { type: 'line', from: [ox + L, oy], to: [ox + L - 250, oy + 120] },
    { type: 'label', at: [ox + L + 250, oy], text: 'x' },
    { type: 'line', from: [ox, oy], to: [ox, oy + L] },
    { type: 'line', from: [ox, oy + L], to: [ox - 120, oy + L - 250] },
    { type: 'line', from: [ox, oy + L], to: [ox + 120, oy + L - 250] },
    { type: 'label', at: [ox, oy + L + 250], text: 'y' },
    { type: 'point', at: [ox, oy] },
    { type: 'handle', at: [ox, oy], x: 'originX', y: 'originY' },
  ];
  if (params.snap) items.push({ type: 'snap', at: [ox, oy] });
  if (t > 0)
    for (let d = t; d < L - 1; d += t) {
      items.push({ type: 'line', from: [ox + d, oy - h], to: [ox + d, oy + h] });
      items.push({ type: 'line', from: [ox - h, oy + d], to: [ox + h, oy + d] });
      if (params.snap) items.push({ type: 'snap', at: [ox + d, oy] }, { type: 'snap', at: [ox, oy + d] });
    }
  return items;
}

rain.script:
// Where an effect goes: the spaces asked for (by id, by name, else every space whose name has the words), each with its level
// and outline; else the whole site
function places(project, which) {
  const levels = project.levels.slice().sort((a, b) => a.elevation - b.elevation);
  const top = Math.max(...levels.map(l => l.elevation + (l.height || 3000)));
  const exact = which ? project.spaces.filter(x => x.id === which || x.name === which) : [];
  const found = exact.length ? exact : which ? project.spaces.filter(x => x.name.includes(which)) : [];
  if (found.length)
    return found.map(s => {
      const outer = s.shape.reduce((a, b) => (areaOf(b.outer) > areaOf(a.outer) ? b : a)).outer;
      const lv = project.levels.find(l => l.id === s.level);
      return { outline: outer, level: s.level, top: top - lv.elevation + 3000, area: areaOf(outer) };
    });
  const ground = levels[0];
  const outer = project.site.boundary;
  return [{ outline: outer, level: ground.id, top: top - ground.elevation + 3000, area: areaOf(outer) }];
}
function areaOf(r) {
  let a = 0;
  for (let i = 0; i < r.length; i++) { const [x0, y0] = r[i], [x1, y1] = r[(i + 1) % r.length]; a += x0 * y1 - x1 * y0; }
  return Math.abs(a) / 2 / 1e6;
}
function widget(project, params, ctx) {
  const ps = places(project, params.space);
  const total = ps.reduce((n, p) => n + p.area, 0);
  const budget = Math.min(20000, Math.max(50, Math.round(total * 80 * params.intensity)));
  return [
    ...ps.map(p => ({ type: 'particles', outline: p.outline, level: p.level, from: 0, to: p.top, count: Math.max(10, Math.round((budget * p.area) / total)), fall: 7 + 3 * params.intensity, drift: 0.1, wind: [params.wind, 0], size: 400, shape: 'streak', tone: 'water' })),
    { type: 'sky', mood: 'overcast' },
    { type: 'fog', density: 0.1 + 0.25 * params.intensity, tone: 'mist' },
  ];
}

