night.script:
function widget(project, params, ctx) {
  const rooms = project.spaces.filter(s => s.kind === 'indoor').map(s => {
    const r = s.shape[0].outer;
    let a = 0, x = 0, y = 0;
    for (let i = 0; i < r.length; i++) { const [x0, y0] = r[i], [x1, y1] = r[(i + 1) % r.length]; const c = x0 * y1 - x1 * y0; a += c; x += (x0 + x1) * c; y += (y0 + y1) * c; }
    return { s, a: Math.abs(a / 2), at: [x / (3 * a), y / (3 * a)] };
  }).sort((p, q) => q.a - p.a).slice(0, 8);
  return [
    { type: 'sky', mood: 'night' },
    ...rooms.map(r => ({ type: 'light', at: r.at, level: r.s.level, z: 2400, intensity: params.brightness, range: 8000, tone: 'warm' })),
  ];
}
